    func path(in rect: CGRect) -> Path {
        let scale = min(rect.width / 512.5, rect.height / 567.5)
        return Self.outline.applying(CGAffineTransform(a: scale, b: 0, c: 0, d: scale,
                                                       tx: rect.midX - 256.25 * scale,
                                                       ty: rect.midY - 283.75 * scale))
    }
